import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-payroll.json"), "utf8"),
);
const models = emitModels(contract.models, "salaryHeadKindSchema");
let go =
  '// Code generated by scripts/generate-workforce-payroll.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
go += `var salaryHeadKinds=[]string{${Object.keys(contract.kinds)
  .map((k) => JSON.stringify(k))
  .join(",")}}\n`;
let ts = '// Generated by scripts/generate-workforce-payroll.mjs.\nimport { z } from "zod";\n\n';
ts += `export const SALARY_HEAD_KINDS=${JSON.stringify(contract.kinds)} as const;\nexport const salaryHeadKindSchema=z.enum(${JSON.stringify(Object.keys(contract.kinds))});\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/payroll_types.go",
  go + models.go,
  "packages/api/src/payroll-contract.ts",
  ts + models.ts,
  "payroll",
);
